/**
 * fix-timezone-accuracy — real engine, real tz database, NO mocks.
 *
 * Every expected value comes from fixtures/independent-reference.json, generated by
 * scripts/verify/independent_reference.py, which shares no code with the site:
 * Python zoneinfo + the IANA `tzdata` package for local→UTC, the exact Swiss-Ephemeris
 * Lahiri definition (+ IAU-2006 precession + nutation) for the ayanamsa, its own
 * Ascendant / mean-node / Vimshottari code (pure-Python astronomy-engine ephemeris).
 */
import { describe, it, expect } from 'vitest';
import ref from './fixtures/independent-reference.json';
import { resolveBirthTimezone, boundaryNote, METHOD_LINE, timezoneForCoordinates } from '../birthTimezone';
import { birthQuery } from '../clientBirth';
import { calculateBirthChart } from '../../vedic/calculateBirthChart';
import { calculateGunaMilan } from '../../vedic/matchmaking';
import { RASHI_NAMES } from '../../vedic/engine/vedicEngine';
import { parseDob } from '../../../components/DobInput';
import { GET as matchGET } from '../../../../api/kundali-match';
import { GET as kundaliGET } from '../../../../api/kundali';

type Case = (typeof ref.cases)[number];
const REF_DATE = new Date(ref.refDate);
const byId = (id: string) => ref.cases.find(c => c.id === id) as Case;
const TZ_CASES = ref.cases.filter(c => c.id !== 'repro-girl-as-ist');

async function engineFor(c: Case) {
  const tz = resolveBirthTimezone({ lat: c.lat, lon: c.lon, year: c.local.y, month: c.local.m, day: c.local.d, hour: c.local.h, minute: c.local.min });
  const chart = await calculateBirthChart({
    year: c.local.y, month: c.local.m, day: c.local.d, hour: c.local.h, minute: c.local.min,
    latitude: c.lat, longitude: c.lon, timezoneOffset: tz.utcOffsetHours,
  }, { refDate: REF_DATE });
  return { tz, chart };
}
const angDiff = (a: number, b: number) => { const d = Math.abs(a - b) % 360; return d > 180 ? 360 - d : d; };

describe('shared timezone resolver vs independent tz database', () => {
  it.each(TZ_CASES.map(c => [c.id, c] as const))('%s: zone, UTC offset, UTC instant, DST flags', (_id, c) => {
    const r = resolveBirthTimezone({ lat: c.lat, lon: c.lon, year: c.local.y, month: c.local.m, day: c.local.d, hour: c.local.h, minute: c.local.min });
    expect(r.timezone).toBe(c.timezone);
    expect(r.utcOffsetHours).toBe(c.utcOffsetHours);
    expect(new Date(r.utcISO).getTime()).toBe(new Date(c.utc).getTime());
    expect(r.ambiguous).toBe(c.ambiguous);
    expect(r.nonexistent).toBe(c.nonexistent);
    if (c.ambiguous || c.nonexistent) expect(r.note).toBeTruthy(); else expect(r.note).toBeNull();
  });

  it('never defaults to IST: non-Indian coordinates never resolve to Asia/Kolkata', () => {
    for (const c of TZ_CASES.filter(x => !x.place.includes('India'))) {
      expect(timezoneForCoordinates(c.lat, c.lon)).not.toBe('Asia/Kolkata');
    }
    // Same-name towns resolve to different zones from their own coordinates.
    expect(timezoneForCoordinates(42.6389, -83.2910)).toBe('America/Detroit');   // Pontiac, Michigan
    expect(timezoneForCoordinates(40.8809, -88.6298)).toBe('America/Chicago');   // Pontiac, Illinois
  });

  it('split-rule and fractional zones', () => {
    const at = (lat: number, lon: number, y: number, m: number, d: number) =>
      resolveBirthTimezone({ lat, lon, year: y, month: m, day: d, hour: 12, minute: 0 }).utcOffsetHours;
    expect(at(-34.9285, 138.6007, 2000, 7, 1)).toBe(9.5);    // Adelaide winter
    expect(at(-34.9285, 138.6007, 2000, 1, 15)).toBe(10.5);  // Adelaide summer (DST)
    expect(at(47.5615, -52.7126, 2000, 1, 15)).toBe(-3.5);   // St John's, Newfoundland
    expect(at(35.6892, 51.389, 2010, 1, 15)).toBe(3.5);      // Tehran
    expect(at(33.4484, -112.074, 2000, 1, 15)).toBe(-7);     // Phoenix winter = summer (no DST)
    expect(at(33.4484, -112.074, 2000, 7, 15)).toBe(-7);
  });

  it('manual IANA zone overrides the coordinates', () => {
    const r = resolveBirthTimezone({ lat: 42.6389, lon: -83.291, year: 1999, month: 12, day: 3, hour: 11, minute: 3, timezone: 'Asia/Kolkata' });
    expect(r.source).toBe('manual');
    expect(r.utcOffsetHours).toBe(5.5);
    expect(() => resolveBirthTimezone({ lat: 0, lon: 0, year: 2000, month: 1, day: 1, hour: 0, minute: 0, timezone: 'Mars/Olympus' })).toThrow();
  });
});

describe('engine Moon sign / nakshatra / pada vs independent calculation', () => {
  it.each(ref.cases.map(c => [c.id, c] as const))('%s', async (_id, c) => {
    const chart = await calculateBirthChart({
      year: c.local.y, month: c.local.m, day: c.local.d, hour: c.local.h, minute: c.local.min,
      latitude: c.lat, longitude: c.lon, timezoneOffset: c.utcOffsetHours,
    }, { refDate: REF_DATE });
    const moon = chart.planets.find(p => p.name === 'Moon')!;
    expect(angDiff(moon.longitude, c.moon.longitude)).toBeLessThan(0.02);
    expect(chart.rashi).toBe(c.moon.rashi);
    expect(chart.nakshatra.nakshatra).toBe(c.moon.nakshatra);
    expect(chart.nakshatra.pada).toBe(c.moon.pada);
  });
});

describe('Kundali check: Lagna, 9 planets (sign + house), current Maha/Antar dasha', () => {
  it.each(['repro-girl', 'new-york-july', 'london-july', 'sydney-jan', 'dubai'])('%s', async (id) => {
    const c = byId(id);
    const { tz, chart } = await engineFor(c);
    expect(tz.utcOffsetHours).toBe(c.utcOffsetHours);
    expect(chart.lagna.sign).toBe(c.lagna.rashi);
    expect(Math.abs(chart.lagna.degrees - c.lagna.degreeInSign)).toBeLessThan(0.1);
    for (const name of ['Sun', 'Moon', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Rahu', 'Ketu']) {
      const p = chart.planets.find(x => x.name === name)!;
      const r = (c.planets as Record<string, { rashi: string; house: number; longitude: number }>)[name];
      expect(p.sign, `${id} ${name} sign`).toBe(r.rashi);
      expect(p.house, `${id} ${name} house`).toBe(r.house);
      expect(angDiff(p.longitude, r.longitude), `${id} ${name} longitude`).toBeLessThan(0.05);
    }
    expect(chart.currentDasha?.mahadasha).toBe(c.dasha!.mahadasha);
    expect(chart.currentDasha?.antardasha).toBe(c.dasha!.antardasha);
  });
});

describe('repro: Suchit (Lucknow) × Sukriti (Pontiac, Michigan) — real /api/kundali-match', () => {
  const base = 'https://bornclock.com/api/kundali-match?yA=1996&mA=08&dA=31&hA=13&minA=04&latA=26.8467&lonA=80.9462'
    + '&yB=1999&mB=12&dB=03&hB=11&minB=03&latB=42.6389216&lonB=-83.2910468';
  const score = (r: { gunaMilan: { kootas: Array<{ key: string; score: number }> } }, k: string) =>
    r.gunaMilan.kootas.find(x => x.key === k)!.score;

  it('girl resolves to America/Detroit UTC−5 → Tula / Chitra pada 3, even if an old client sends tzB=5.5', async () => {
    for (const url of [base, base + '&tzA=5.5&tzB=5.5']) {
      const r = await (await matchGET(new Request(url))).json();
      expect(r.people.a).toMatchObject({ timezone: 'Asia/Kolkata', utcOffsetHours: 5.5, rashi: 'Meena', nakshatra: 'Revati', pada: 1, lagna: 'Vrischika' });
      expect(r.people.b).toMatchObject({ timezone: 'America/Detroit', utcOffsetHours: -5, rashi: 'Tula', nakshatra: 'Chitra', pada: 3, lagna: 'Makara' });
      expect(r.people.b.utcISO).toBe('1999-12-03T16:03:00.000Z');
      expect(r.people.b.moonDegreeInSign).toBeCloseTo(0.28, 1);
      expect(r.people.b.notes).toContain('Moon is near a sign boundary. A small birth-time difference can change this result. Please double-check the birth time.');
      expect(r.method).toBe(METHOD_LINE);
      // The timezone-sensitive kootas now agree with Astrotalk exactly:
      expect(score(r, 'varna')).toBe(1);
      expect(score(r, 'tara')).toBe(1.5);
      expect(score(r, 'graha_maitri')).toBe(0.5);
      expect(score(r, 'bhakoot')).toBe(0);
      expect(score(r, 'nadi')).toBe(8);
      // Rule-dependent kootas now follow AstroSage (17 Oct 2026, round2 audit): Vashya ½, Yoni 1, Gana 0.
      expect(score(r, 'vashya')).toBe(0.5);
      expect(score(r, 'yoni')).toBe(1);
      expect(score(r, 'gana')).toBe(0);
      expect(r.gunaMilan.total).toBe(12.5); // = AstroSage 12.5
    }
  });

  it('the old bug, reproduced on purpose via a manual IST zone: Kanya, Bhakut 7, total 19.5 (22 under the old tables)', async () => {
    const r = await (await matchGET(new Request(base + '&tzidB=Asia/Kolkata'))).json();
    expect(r.people.b).toMatchObject({ timezone: 'Asia/Kolkata', timezoneSource: 'manual', rashi: 'Kanya', nakshatra: 'Chitra', pada: 1 });
    expect(score(r, 'bhakoot')).toBe(7);
    // Same wrong Moon sign; the AstroSage tables change Vashya/Yoni/Gana (−0.5 −1 −1).
    expect(r.gunaMilan.total).toBe(19.5);
  });

  it('an unknown manual zone is a clean 400', async () => {
    const res = await matchGET(new Request(base + '&tzidB=Not/AZone'));
    expect(res.status).toBe(400);
  });
});

describe('koota rules fed the CORRECT Moons directly (AstroSage tables)', () => {
  it('Revati p1 / Meena × Chitra p3 / Tula', () => {
    const g = calculateGunaMilan(
      { nakshatra: 'Revati', pada: 1, rashiIndex: RASHI_NAMES.indexOf('Meena') },
      { nakshatra: 'Chitra', pada: 3, rashiIndex: RASHI_NAMES.indexOf('Tula') },
    );
    const s = Object.fromEntries(g.kootas.map(k => [k.key, k.score]));
    // AstroSage, 17 Oct 2026 (round2 audit): total 12.5 with Vashya ½, Yoni 1, Gana 0.
    expect(s).toEqual({ varna: 1, vashya: 0.5, tara: 1.5, yoni: 1, graha_maitri: 0.5, gana: 0, bhakoot: 0, nadi: 8 });
    expect(g.total).toBe(12.5);
  });
});

describe('real /api/kundali (Kundali page) — foreign birth', () => {
  it('New York July birth: EDT applied, birthTimezone returned, legacy tz ignored', async () => {
    const c = byId('new-york-july');
    const url = `https://bornclock.com/api/kundali?y=1990&m=7&d=15&h=8&min=30&lat=${c.lat}&lon=${c.lon}&tz=5.5`;
    const r = await (await kundaliGET(new Request(url), {})).json();
    expect(r.birthTimezone).toMatchObject({ timezone: 'America/New_York', utcOffsetHours: -4 });
    expect(r.lagna.sign).toBe(c.lagna.rashi);
    expect(r.rashi).toBe(c.moon.rashi);
  });
});

describe('date format: 03/12/1999 means 3 December everywhere', () => {
  it('DobInput (DD / MM / YYYY fields)', () => {
    const { date } = parseDob('03', '12', '1999');
    expect(date?.getFullYear()).toBe(1999);
    expect(date?.getMonth()).toBe(11);
    expect(date?.getDate()).toBe(3);
  });
  it('birth query sent to every API (ISO dob → m=12, d=03)', () => {
    const q = birthQuery('1999-12-03', '11:03', { lat: 42.6389, lon: -83.291 });
    expect(q).toMatchObject({ y: '1999', m: '12', d: '03', h: '11', min: '03', tz: '-5' });
  });
  it('the timezone resolver treats month=12 / day=3 as 3 December (not 12 March)', () => {
    const r = resolveBirthTimezone({ lat: 42.6389, lon: -83.291, year: 1999, month: 12, day: 3, hour: 11, minute: 3 });
    expect(r.utcISO).toBe('1999-12-03T16:03:00.000Z');
    expect(r.utcOffsetHours).toBe(-5); // 12 March 1999 would also be EST, so check the date itself above
  });
  it('a slash date is never accepted as a carried ?dob= (ISO only)', () => {
    const iso = /^\d{4}-\d{2}-\d{2}$/;
    expect(iso.test('03/12/1999')).toBe(false);
    expect(iso.test('1999-12-03')).toBe(true);
  });
});

describe('boundary note', () => {
  it('fires within 1° of a sign or nakshatra edge, for Moon and Lagna wording', () => {
    expect(boundaryNote('Moon', 180.28)).toBe('Moon is near a sign boundary. A small birth-time difference can change this result. Please double-check the birth time.');
    expect(boundaryNote('Lagna', 89.7)).toBe('Lagna is near a sign boundary. A small birth-time difference can change this result. Please double-check the birth time.');
    expect(boundaryNote('Moon', 349.54)).toBeNull(); // repro boy: 10.5° from sign, 2.9° from nakshatra edge
    expect(boundaryNote('Moon', 13.5)).toBeTruthy();  // 0.17° past Ashwini/Bharani edge
  });
});
